Here's a Python function that checks if a string containing only bracket characters is balanced using a stack:

```python
def are_brackets_balanced(s: str) -> bool:
  """
  Checks if a string containing only the bracket characters
  '(', ')', '[', ']', '{', '}' has balanced brackets.

  Args:
    s: The string to check.

  Returns:
    True if the brackets are balanced, False otherwise.
  """
  stack = []
  brackets = {
    ')': '(',
    '}': '{',
    '[': ']'
  }
  for char in s:
    if char in brackets.values():
      if char in '({[':
        stack.append(char)
      else:
        # No need to check for matching ']' as it is a closing bracket for all opening brackets
        return False
    elif char in brackets.keys():
      if len(stack) == 0:
        return False  
      else:
        stack.pop()  
