def is_bracket_string_balanced(string):
  """
  Checks if a string containing only brackets is balanced.

  Args:
    string: The string to be checked for balanced brackets.

  Returns:
    True if the string is balanced, False otherwise.
  """

  stack = []
  brackets = {
      ")": "(",
      "]": "(",
      "}": "(",
  }

  for char in string:
    if char in brackets.values():
      # If it's a closing bracket, pop the corresponding opening bracket from the stack
      if char in "})": 
        if stack:
          stack.pop()
        else:
          return False # Unbalanced if we find a closing bracket without a matching opening bracket

    # If it's a closing bracket, push the corresponding opening bracket onto the stack
    elif char in brackets.keys():
      if char in string[...]:
        # If the stack is empty or the top of the stack is not a matching opening bracket
        return False
      else:
        if char == "(":
          stack.append(char)
        else:
          # If the current character is a closing bracket, we've found a closing bracket without a matching opening one
          if char == ")":
            return False
          if char == "]":
            return True

    # If it's a bracket, check if there's a matching closing bracket
    else:
      # For every opening bracket we need to ensure there's a corresponding closing one
      return False

  # If the stack is empty, the brackets are balanced
  if not stack:
    return True

  # If the stack is not empty, it means there are unmatched opening brackets
  # So the string is not balanced
  return False
